export const benefitCoordinationDefinitions={
  benefitCoordination:{title:'Coordinate two hypothetical plan amounts against one common eligible expense',fields:[
    ['commonEligible','Expense assumed eligible on the same basis under both plans (CAD)',1500,0,30000,100],
    ['outsideEligibility','Additional invoiced amount assumed ineligible under both plans (CAD)',200,0,10000,50],
    ['primaryRate','Primary plan’s modeled percentage of the common eligible expense (%)',70,0,100,5],
    ['primaryCapLeft','Primary plan’s unused maximum available for this claim (CAD)',1000,0,10000,100],
    ['secondaryRate','Secondary standalone percentage of the same eligible expense (%)',60,0,100,5],
    ['secondaryCapLeft','Secondary plan’s unused maximum available for this claim (CAD)',1000,0,10000,100]
  ]}
};
export function coordinatedBenefit(input,commonEligible=input.commonEligible,primaryCapLeft=input.primaryCapLeft,secondaryCapLeft=input.secondaryCapLeft){
  const primaryPotential=Math.min(commonEligible*input.primaryRate/100,primaryCapLeft);
  const secondaryPotential=Math.min(commonEligible*input.secondaryRate/100,secondaryCapLeft);
  const primary=primaryPotential,secondary=Math.min(Math.max(0,commonEligible-primary),secondaryPotential);
  const uncoveredEligible=Math.max(0,commonEligible-primary-secondary),invoice=commonEligible+input.outsideEligibility;
  return {primaryPotential,secondaryPotential,primary,secondary,uncoveredEligible,invoice,household:uncoveredEligible+input.outsideEligibility,primaryOnly:commonEligible-primary+input.outsideEligibility};
}
export function benefitCoordinationResult(kind,input){
  if(kind!=='benefitCoordination')throw Error('Unknown benefit-coordination topic.');
  const p=coordinatedBenefit(input),maximum=Math.max(5000,input.commonEligible),expenses=Array.from({length:51},(_,i)=>maximum*i/50);
  return {metrics:[['Primary payment under the selected teaching formula',p.primary,'money'],['Coordinated secondary payment under that formula',p.secondary,'money'],['Household share, including the separately ineligible amount',p.household,'money']],note:'Original two-plan teaching formula, not an insurer claim decision. Primary and secondary status are assumed already confirmed; this calculator does not determine or let the claimant choose priority. Both plans are assumed to use the same entered eligible expense. Primary pays the lesser of its percentage amount and unused maximum. Secondary pays the least of the remaining common eligible expense, its standalone percentage amount and its unused maximum. The secondary percentage applies to the original common eligible expense, not to the unpaid remainder. The separately entered ineligible amount is covered by neither plan. No deductible, differing eligible-fee schedules, exclusions, service limits, tax, premium, claim date or reimbursement delay is modeled. Rates, maximums and eligibility must be checked in the actual plans; different terms require different calculations.',charts:[
    {id:'benefit-coordination-invoice',type:'stackbar',title:'Allocate one invoice across the two modeled payments and the household share',unit:'money',seriesNames:['Primary plan','Coordinated secondary plan','Household share'],rows:[{label:'One invoice · includes the separately ineligible amount',values:[p.primary,p.secondary,p.household]}],note:'The three parts reconcile to the full entered invoice: common eligible expense plus the amount ineligible under both plans. A 100% combined reimbursement of the common eligible expense still leaves the separately ineligible amount to fund. No payment is counted twice.'},
    {id:'benefit-coordination-standalone',type:'groupbar',title:'Standalone percentage amounts do not simply add into a coordinated claim',unit:'money',seriesNames:['Modeled standalone amount after its cap','Modeled coordinated payment'],rows:[{label:'Confirmed primary plan',values:[p.primaryPotential,p.primary]},{label:'Confirmed secondary plan',values:[p.secondaryPotential,p.secondary]}],note:'Each standalone amount applies that plan’s percentage and unused maximum to the same common eligible expense before coordination. The secondary payment is then limited by what remains unpaid on that common basis. The primary result is unchanged. This exercise assumes a specified formula and supplies no actual insurer benefit amount.'},
    {id:'benefit-coordination-expense-path',type:'line',title:'Larger claims can exhaust the selected unused maximums',unit:'money',xUnit:'money',xLabel:'Common eligible expense (CAD)',series:[['Household share with the primary plan only','primaryOnly'],['Household share with both modeled plans','household']].map(([name,key],i)=>({name,dash:i===1,rows:expenses.map(expense=>({x:expense,value:coordinatedBenefit(input,expense)[key]}))})),note:'The horizontal axis changes the common eligible expense, while both rates, unused maximums and the separately ineligible amount stay selected. The ineligible amount therefore remains in the household share even at zero common eligible expense. These are distinct hypothetical claim sizes, not cumulative claims, changing balances over time or probabilities.'},
    {id:'benefit-coordination-cap-matrix',type:'heatmap',title:'The household share depends on unused maximums as well as headline percentages',unit:'money',unitLabel:'Rows: primary unused maximum · columns: secondary unused maximum · cells: CAD household share',columns:['$0','$250','$500','$1k'],rows:[[0,'$0'],[500,'$500'],[1000,'$1k'],[1500,'$1.5k']].map(([primaryCapLeft,label])=>({label,values:[0,250,500,1000].map(secondaryCapLeft=>coordinatedBenefit(input,input.commonEligible,primaryCapLeft,secondaryCapLeft).household)})),note:'Rows and columns replace the two unused maximums. Common eligible expense, the amount ineligible under both plans and both percentage rates stay selected. These maximums are amounts available for this claim, not the original annual limits or evidence of coverage. A zero cell can occur only when the selected modeled invoice is fully funded by the two payments. No calendar reset or renewal is assumed.'}
  ]};
}
